# Sampling error and paired time-resolution diagnostics.
simulation_convergence<-function(runs,shared_innovations,sampling_contract,precision,design,context=NULL){
 d<-.vb_design(design,context,FALSE);contract<-.ex_object(sampling_contract,'sampling_contract');p<-.ex_object(precision,'precision');innovations<-.ex_object(shared_innovations,'shared_innovations');if(!identical(contract$sampling_unit,'iid_paths_with_independent_replicates')||!(contract$metric%in%c('mean','bernoulli_probability'))).cr_error('CONVERGENCE_SAMPLING','Declare iid paths, independent replicates and metric');.vb_string(contract$reference,'sampling reference');finest<-.vb_number(contract$finest_time_step,'finest_time_step',0);if(finest==0).cr_error('CONVERGENCE_GRID','Finest time step must be positive');if(!identical(contract$time_unit,d$target$time_unit)).cr_error('CONVERGENCE_GRID','Time step units must match target');level<-.vb_number(p$confidence_level,'confidence_level');tol<-.vb_number(p$mc_half_width,'mc_half_width',0);gridtol<-.vb_number(p$grid_difference_tolerance,'grid_difference_tolerance',0);if(level<=0||level>=1).cr_error('CONVERGENCE_PRECISION','Interior confidence level required');z<-stats::qnorm((1+level)/2);matrices<-path_ids<-list()
 for(rep in names(innovations)){.vb_string(rep,'replicate_id');entry<-.ex_object(innovations[[rep]],'shared innovation entry');v<-.ex_matrix(entry$values,'shared innovations');ids<-.ex_ids(entry$path_ids,'path_ids');if(nrow(v)!=length(ids)||ncol(v)<1).cr_error('CONVERGENCE_INNOVATIONS','Path-by-innovation matrix and aligned IDs required');matrices[[rep]]<-v;path_ids[[rep]]<-ids};if(!is.list(runs)||!length(runs)).cr_error('CONVERGENCE_RUNS','Nonempty run array required');indexed<-list();trace<-list();triples<-list();runkey<-function(dt,N,rep).cr_hash(list(dt,N,rep))
 for(run in runs){run<-.ex_object(run,'run');rep<-run$replicate_id;dt<-.vb_number(run$time_step,'time_step',0);N<-.vb_number(run$sample_size,'sample_size',2);values<-.vb_vec(run$values,'run values');if(is.null(rep)||!rep%in%names(matrices)||N!=floor(N)||dt<=0||abs(dt/finest-round(dt/finest))>1e-10).cr_error('CONVERGENCE_RUN','Known replicate, integer count and nested grid required');ids<-.ex_ids(run$path_ids,'run path IDs');if(length(values)!=N||N>length(path_ids[[rep]])||!identical(ids,path_ids[[rep]][seq_len(N)])).cr_error('CONVERGENCE_NESTING','Values and IDs must be declared prefix');expected<-.cr_hash(.ex_rows(matrices[[rep]][seq_len(N),,drop=FALSE]));if(!identical(run$innovation_fingerprint,expected)).cr_error('CONVERGENCE_NESTING','Run fingerprint differs from shared prefix');if(contract$metric=='bernoulli_probability'&&any(!(values%in%c(0,1)))).cr_error('CONVERGENCE_BERNOULLI','Bernoulli values must be zero or one');key<-runkey(dt,N,rep);if(!is.null(indexed[[key]])).cr_error('CONVERGENCE_DUPLICATE','Duplicate run');indexed[[key]]<-values;triples[[length(triples)+1]]<-list(dt=dt,N=N,rep=rep);trace[[length(trace)+1]]<-list(replicate_id=rep,time_step=dt,sample_size=N,path_ids=as.list(ids),innovation_fingerprint=expected)}
 levels<-unique(do.call(rbind,lapply(triples,function(x)c(x$dt,x$N))));levels<-levels[order(levels[,1],levels[,2]),,drop=FALSE];reps<-sort(names(matrices));for(i in seq_len(nrow(levels))){dt<-levels[i,1];N<-levels[i,2];present<-vapply(Filter(function(x)x$dt==dt&&x$N==N,triples),function(x)x$rep,character(1));if(!setequal(present,reps)).cr_error('CONVERGENCE_REPLICATES','Every level must contain every declared replicate')}
 summary<-function(v,bernoulli=FALSE){N<-length(v);m<-mean(v);se<-stats::sd(v)/sqrt(N);half<-z*se;lower<-m-half;upper<-m+half;method<-'IID_NORMAL_APPROXIMATION';if(bernoulli){den<-1+z*z/N;center<-(m+z*z/(2*N))/den;half<-z*sqrt(m*(1-m)/N+z*z/(4*N*N))/den;lower<-max(0,center-half);upper<-min(1,center+half);method<-'IID_WILSON_SCORE';half<-max(m-lower,upper-m)};if(any(!is.finite(c(m,se,lower,upper,half)))).cr_error('CONVERGENCE_NUMERICAL','Statistic exceeds finite range');list(n=N,estimate=m,mc_standard_error=se,lower=lower,upper=upper,maximum_interval_radius=half,interval_method=method,mc_precision_met=half<=tol)}
 estimates<-list();for(i in seq_len(nrow(levels))){dt<-levels[i,1];N<-levels[i,2];values<-unlist(lapply(reps,function(rep)indexed[[runkey(dt,N,rep)]]),use.names=FALSE);s<-summary(values,contract$metric=='bernoulli_probability');s$time_step<-dt;s$paths_per_replicate<-N;s$replicate_estimates<-setNames(lapply(reps,function(rep)mean(indexed[[runkey(dt,N,rep)]])),reps);estimates[[length(estimates)+1]]<-s};comparisons<-list();for(N in sort(unique(levels[,2]))){grids<-sort(levels[levels[,2]==N,1]);if(length(grids)>1)for(i in seq_len(length(grids)-1)){fine<-grids[i];coarse<-grids[i+1];difference<-unlist(lapply(reps,function(rep)indexed[[runkey(coarse,N,rep)]]-indexed[[runkey(fine,N,rep)]]),use.names=FALSE);s<-summary(difference);s$mc_precision_met<-NULL;s$coarse_time_step<-coarse;s$fine_time_step<-fine;s$paths_per_replicate<-N;s$orientation<-'COARSE_MINUS_FINE';s$absolute_difference_upper_bound<-max(abs(s$lower),abs(s$upper));s$observed_grid_tolerance_met<-s$absolute_difference_upper_bound<=gridtol;comparisons[[length(comparisons)+1]]<-s}}
 reference<-contract$analytic_reference;analytic<-NULL;if(!is.null(reference)){reference<-.ex_object(reference,'analytic_reference');value<-.vb_number(reference$value,'analytic reference');.vb_string(reference$source,'analytic source');analytic<-lapply(estimates,function(s)list(time_step=s$time_step,paths_per_replicate=s$paths_per_replicate,absolute_error=abs(s$estimate-value),reference_in_interval=s$lower<=value&&value<=s$upper))};out<-list(artifact_type='ValidationResult',metrics=list(sampling=estimates,paired_grid_differences=comparisons,analytic_reference_comparisons=analytic),design=d,sampling_contract=contract,precision=p,innovation_nesting=trace,uncertainty=list(independence='DECLARED_NOT_AUTHENTICATED',confidence_level=level,multiplicity='UNADJUSTED_DIAGNOSTIC_INTERVALS'),discretization_bias_identified=FALSE,decision=list(status='DIAGNOSTIC_ONLY',reason='Successive grid differences do not bound error to continuous-time limit'),applicability='APPLICABLE',input_fingerprint=.cr_hash(runs),shared_innovation_fingerprint=.cr_hash(innovations));.cr_result(out,'validation.simulation_convergence','simulation_precision',context,limitations='More paths reduce sampling error, not discretization bias. Fingerprints verify declared inputs and path nesting, not external simulator execution. General mean intervals are asymptotic; Wilson avoids zero-width zero-default inference.')
}

sensitivity_analysis<-function(model,baseline,perturbations,method,shared_samples,design,context=NULL){
 d<-.vb_design(design,context,FALSE);descriptor<-.ex_object(model,'evaluation model');x<-.vb_vec(baseline,'baseline');specs<-perturbations;if(!is.list(specs)||length(specs)!=length(x)||!length(x)).cr_error('SENSITIVITY_DOMAIN','One specification per nonempty baseline coordinate required');coordnames<-.ex_ids(lapply(specs,function(s)s$name),'coordinate names');lower<-upper<-steps<-numeric();locations<-list();kind<-descriptor$kind
 if(identical(kind,'pd_model')){fitted<-.cr_model(descriptor$fitted_model);descriptor$fitted_model<-fitted;if(.cr_hash(fitted$target)!=.cr_hash(d$target)||.cr_data_date(fitted$training$known_at,'model known_at')>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')).cr_error('SENSITIVITY_MODEL','Frozen model target/date differs from design');if(!identical(coordnames,as.character(unlist(fitted$feature_order)))).cr_error('SENSITIVITY_FEATURES','Coordinate names must equal trained feature order')}else if(identical(kind,'model_graph')){for(key in c('model_graph','input_data','parameter_snapshots','execution_context')).ex_object(descriptor[[key]],key)}else .cr_error('SENSITIVITY_MODEL','Use frozen pd_model or model_graph evaluator')
 key_index<-function(obj,key){if(is.numeric(key)&&length(key)==1&&is.finite(key)&&key==floor(key)&&key>=0){j<-key+1;if(j>length(obj)).cr_error('SENSITIVITY_PATH','Unknown numeric index');j}else if(is.character(key)&&length(key)==1&&key%in%names(obj))key else .cr_error('SENSITIVITY_PATH','Unknown intervention path')}
 get_path<-function(obj,path){for(key in path)obj<-obj[[key_index(obj,key)]];obj}
 set_path<-function(obj,path,value){key<-key_index(obj,path[[1]]);if(length(path)==1)obj[[key]]<-value else obj[[key]]<-set_path(obj[[key]],path[-1],value);obj}
 for(i in seq_along(specs)){spec<-specs[[i]];a<-.vb_number(spec$lower,'lower');b<-.vb_number(spec$upper,'upper');h<-.vb_number(spec$step,'step',0);if(x[i]<a||x[i]>b||a>=b||h<=0).cr_error('SENSITIVITY_DOMAIN','Baseline in nondegenerate bounds and positive step required');lower<-c(lower,a);upper<-c(upper,b);steps<-c(steps,h);if(kind=='pd_model'){if(!identical(spec$location,'feature')).cr_error('SENSITIVITY_PATH','PD coordinates modify features; use graph for parameters');locations[i]<-list(NULL)}else{path<-as.list(spec$path);location<-spec$location;if(!length(path)).cr_error('SENSITIVITY_PATH','Explicit zero-based path required');if(identical(location,'input')){if(length(path)<3||!identical(path[[2]],'value')).cr_error('SENSITIVITY_PATH','Input interventions change value leaves only');root<-'input_data'}else if(identical(location,'parameter')){if(length(path)<4||!identical(path[[1]],'nodes')||!is.numeric(path[[2]])||path[[2]]!=floor(path[[2]])||!identical(path[[3]],'parameters')).cr_error('SENSITIVITY_PATH','Parameter interventions change node parameter leaves only');root<-'model_graph'}else .cr_error('SENSITIVITY_PATH','Graph coordinates identify input/parameter leaves');value<-.vb_number(get_path(descriptor[[root]],path),'baseline graph leaf');if(value!=x[i]).cr_error('SENSITIVITY_BASELINE','Baseline must equal frozen graph leaf');locations[[i]]<-list(root,path)}}
 if(kind=='model_graph'&&anyDuplicated(vapply(locations,.cr_hash,character(1)))).cr_error('SENSITIVITY_PATH','Duplicate intervention paths');cache<-new.env(parent=emptyenv());trace<-list()
 evaluate<-function(v){v<-as.numeric(v);if(length(v)!=length(x)||any(!is.finite(v))||any(v<lower|v>upper)).cr_error('SENSITIVITY_DOMAIN','Intervention outside domain');key<-.cr_hash(as.list(v));if(exists(key,envir=cache,inherits=FALSE))return(get(key,envir=cache,inherits=FALSE));if(kind=='pd_model')result<-as.numeric(unlist(predict_pd(descriptor$fitted_model,matrix(v,nrow=1),feature_order=coordnames,expected_target=d$target,context=context)$value))[1]else{altered<-descriptor;for(i in seq_along(v)){root<-locations[[i]][[1]];path<-locations[[i]][[2]];altered[[root]]<-set_path(altered[[root]],path,v[i])};replay<-evaluate_model_graph(altered$model_graph,altered$input_data,altered$parameter_snapshots,context=altered$execution_context)$value;final<-replay$final;row<-if(is.null(descriptor$output_row))0 else descriptor$output_row;if(!is.numeric(row)||length(row)!=1||row!=floor(row)||row<0||row>=length(final$value)||final$contract$unit=='design').cr_error('SENSITIVITY_OUTPUT','Scalar final output row required');if(.cr_hash(final$contract$target)!=.cr_hash(d$target)||replay$context$known_at!=d$evaluation_cutoff).cr_error('SENSITIVITY_TARGET','Graph output target/cutoff differs from design');result<-.vb_number(final$value[[row+1]],'graph output')};assign(key,result,envir=cache);trace[[length(trace)+1]]<<-list(coordinates=as.list(v),value=result);result}
 base<-evaluate(x);samples_info<-NULL
 if(method=='finite_difference'){if(!is.null(shared_samples)).cr_error('SENSITIVITY_SAMPLES','Local differentiation consumes no random samples');derivatives<-list();for(j in seq_along(x)){h<-steps[j];left<-x[j]-lower[j];right<-upper[j]-x[j];if(min(left,right)>0){scheme<-'central';h<-min(h,left,right)}else if(right>0){scheme<-'forward';h<-min(h,right/2)}else{scheme<-'backward';h<-min(h,left/2)};derivative<-function(step){direction<-rep(0,length(x));direction[j]<-step;if(scheme=='central')return((evaluate(x+direction)-evaluate(x-direction))/(2*step));if(scheme=='forward')return((-3*base+4*evaluate(x+direction)-evaluate(x+2*direction))/(2*step));(3*base-4*evaluate(x-direction)+evaluate(x-2*direction))/(2*step)};if(h/2==0||(x[j]+h/2==x[j]&&x[j]-h/2==x[j])).cr_error('SENSITIVITY_NUMERICAL','Step not representable at baseline scale');full<-derivative(h);half<-derivative(h/2);if(any(!is.finite(c(full,half)))).cr_error('SENSITIVITY_NUMERICAL','Derivative exceeds range');derivatives[[length(derivatives)+1]]<-list(coordinate=coordnames[j],scheme=scheme,step=h,derivative=half,coarse_derivative=full,step_halving_difference=abs(half-full),elasticity=if(base==0)NULL else half*x[j]/base)};result<-list(baseline_value=base,local_derivatives=derivatives)
 }else if(method=='variance_based'){sample<-.ex_object(shared_samples,'shared_samples');distribution<-.ex_object(sample$distribution_contract,'distribution_contract');if(!identical(distribution$independent_inputs,TRUE)).cr_error('SENSITIVITY_DEPENDENCE','Sobol indices require independent coordinate distributions');.vb_string(distribution$reference,'distribution reference');A<-.ex_matrix(sample$A,'A');B<-.ex_matrix(sample$B,'B');if(!identical(dim(A),dim(B))||ncol(A)!=length(x)||nrow(A)<2).cr_error('SENSITIVITY_SAMPLES','Equal nontrivial A/B matrices required');ya<-vapply(seq_len(nrow(A)),function(i)evaluate(A[i,]),numeric(1));yb<-vapply(seq_len(nrow(B)),function(i)evaluate(B[i,]),numeric(1));combined<-c(ya,yb);variance<-mean((combined-mean(combined))^2);first<-total<-list();for(j in seq_along(x)){C<-A;C[,j]<-B[,j];yc<-vapply(seq_len(nrow(C)),function(i)evaluate(C[i,]),numeric(1));first[j]<-list(if(variance==0)NULL else 1-mean((yb-yc)^2)/(2*variance));total[j]<-list(if(variance==0)NULL else mean((ya-yc)^2)/(2*variance))};interactions<-list();if(length(x)>1)for(j in seq_len(length(x)-1))for(k in seq.int(j+1,length(x))){C<-A;C[,c(j,k)]<-B[,c(j,k)];yc<-vapply(seq_len(nrow(C)),function(i)evaluate(C[i,]),numeric(1));closed<-if(variance==0)NULL else 1-mean((yb-yc)^2)/(2*variance);interactions[[length(interactions)+1]]<-list(coordinates=as.list(coordnames[c(j,k)]),second_order=if(variance==0)NULL else closed-first[[j]]-first[[k]])};if(!is.finite(variance)||any(!is.finite(unlist(c(first,total,lapply(interactions,function(r)r$second_order)))))).cr_error('SENSITIVITY_NUMERICAL','Variance estimator exceeds range');result<-list(baseline_value=base,variance=variance,first_order=setNames(first,coordnames),total_order=setNames(total,coordnames),pairwise_interactions=interactions,applicability=if(variance==0)'NOT_APPLICABLE'else'APPLICABLE',reason=if(variance==0)'ZERO_OUTPUT_VARIANCE'else NULL,finite_sample_indices_clipped=FALSE);samples_info<-list(sample_fingerprint=.cr_hash(sample),rows=nrow(A),distribution_contract=distribution,estimator='JANSEN_SHARED_A_B_HYBRIDS_POPULATION_VARIANCE',uncertainty='NOT_ESTIMATED',independent_sampling_assumption='DECLARED_NOT_AUTHENTICATED')
 }else .cr_error('SENSITIVITY_METHOD','Use finite_difference or variance_based')
 out<-list(artifact_type='ValidationResult',metrics=result,method=method,design=d,baseline=as.list(x),perturbations=specs,evaluation_count=length(trace),evaluation_trace=trace,shared_samples=samples_info,model_fingerprint=.cr_hash(descriptor),causal_effect_identified=FALSE,decision=list(status='DIAGNOSTIC_ONLY'),randomness='FROZEN_DETERMINISTIC_EVALUATION_WITH_SHARED_SAMPLE_DESIGN');.cr_result(out,'validation.sensitivity_analysis','sensitivity',context,limitations='Numerical local derivatives require care for nonsmooth models. Frozen graph parameter interventions are explicit. Sobol decomposition assumes independent inputs and is not causal; finite-sample indices remain unclipped.')
}
